// Stand-in for the Grok platform's server-function wrapper.
//
// grok/src/lib/market.ts starts with
//     import { createServerFn } from "@tanstack/react-start";
// and wraps its market read as
//     createServerFn({ method: "POST" }).validator(check).handler(read)
// On Grok that wrapper turns the read into a call from the browser to the
// server. Here there is no browser, so this does the same two steps in place:
// run the validator on the input, then hand its result to the handler.
// It adds nothing and removes nothing from the read itself.

export function createServerFn() {
  let validate = (input) => input;
  const builder = {
    validator(fn) {
      validate = fn;
      return builder;
    },
    inputValidator(fn) {
      validate = fn;
      return builder;
    },
    handler(fn) {
      return async (args) => fn({ data: validate(args ? args.data : undefined) });
    },
  };
  return builder;
}
